import sys

MOD = 998244353
G = 3


def ntt(a, invert):
    n = len(a)

    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]

    length = 2
    while length <= n:
        wlen = pow(G, (MOD - 1) // length, MOD)
        if invert:
            wlen = pow(wlen, MOD - 2, MOD)

        half = length >> 1
        for start in range(0, n, length):
            w = 1
            end = start + half
            for i in range(start, end):
                u = a[i]
                v = a[i + half] * w % MOD
                a[i] = (u + v) % MOD
                a[i + half] = (u - v) % MOD
                w = w * wlen % MOD
        length <<= 1

    if invert:
        inv_n = pow(n, MOD - 2, MOD)
        for i in range(n):
            a[i] = a[i] * inv_n % MOD


def add_convolution(acc, f, fact, t, l, m, r):
    width = m - l
    min_t = t[m]
    max_x = t[r - 1] - min_t
    h_len = max_x + width + 1

    # For source i=l+a and query q with x=t[q]-min_t:
    # fact[t[q]-i] = H[x + width - a],
    # where H[u] = fact[min_t + u - width].
    work = width * h_len
    if work <= 256:
        for q in range(m, r):
            tq = t[q]
            total = 0
            for i in range(l, m):
                k = tq - i
                if 0 <= k < len(fact):
                    total += f[i] * fact[k]
            acc[q] = (acc[q] + total) % MOD
        return

    size = 1
    need = width + h_len - 1
    while size < need:
        size <<= 1

    a = [0] * size
    b = [0] * size

    for i in range(width):
        a[i] = f[l + i]

    for u in range(h_len):
        k = min_t + u - width
        if 0 <= k < len(fact):
            b[u] = fact[k]

    ntt(a, False)
    ntt(b, False)
    for i in range(size):
        a[i] = a[i] * b[i] % MOD
    ntt(a, True)

    for q in range(m, r):
        idx = t[q] - min_t + width
        acc[q] = (acc[q] + a[idx]) % MOD


def solve():
    input = sys.stdin.readline
    n = int(input())
    s = input().strip()

    if s[0] != "B" or s[-1] != "W":
        print(0)
        return

    fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = fact[i - 1] * i % MOD

    inv_fact = [1] * (n + 1)
    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % MOD

    # t[j] is the number of W's before the (j+1)-st B.
    t = [0] * n
    whites = 0
    blacks = 0
    for c in s:
        if c == "W":
            whites += 1
        else:
            blacks += 1
            if blacks >= 2:
                t[blacks - 1] = whites

    for j in range(1, n):
        if t[j] == n:
            print(0)
            return

    f = [0] * n
    acc = [0] * n
    f[0] = 1

    sys.setrecursionlimit(1_000_000)

    def cdq(l, r):
        if r - l == 1:
            if l == 0:
                return
            if t[l] < l:
                f[l] = 0
            else:
                f[l] = -acc[l] * inv_fact[t[l] - l] % MOD
            return

        m = (l + r) >> 1
        cdq(l, m)
        add_convolution(acc, f, fact, t, l, m, r)
        cdq(m, r)

    cdq(0, n)

    ans = fact[n]
    for j in range(1, n):
        ans = (ans + f[j] * fact[n - j]) % MOD
    print(ans)


if __name__ == "__main__":
    solve()

import sys
from array import array
from bisect import bisect_left


class RangeTree2D:
    def __init__(self, points, n):
        size = 1
        while size < n:
            size <<= 1
        self.size = size

        vals = [[] for _ in range(2 * size)]
        for a, b in points:
            p = a - 1 + size
            while p:
                vals[p].append(b)
                p >>= 1

        self.coords = [None] * (2 * size)
        self.seg = [None] * (2 * size)

        for p in range(1, 2 * size):
            if vals[p]:
                coord = sorted(set(vals[p]))
                self.coords[p] = coord
                s = 1
                while s < len(coord):
                    s <<= 1
                self.seg[p] = array("i", [0]) * (2 * s)

    def clear(self):
        for i in range(1, len(self.seg)):
            if self.seg[i] is not None:
                self.seg[i] = array("i", [0]) * len(self.seg[i])

    def update(self, a, b, value):
        p = a - 1 + self.size
        while p:
            coord = self.coords[p]
            if coord is not None:
                k = bisect_left(coord, b)
                seg = self.seg[p]
                base = len(seg) // 2
                q = base + k

                if seg[q] < value:
                    seg[q] = value
                    q >>= 1
                    while q:
                        nv = seg[q << 1]
                        if seg[q << 1 | 1] > nv:
                            nv = seg[q << 1 | 1]
                        if seg[q] == nv:
                            break
                        seg[q] = nv
                        q >>= 1
            p >>= 1

    def query_node(self, p, lo, hi):
        coord = self.coords[p]
        if coord is None:
            return 0

        left = bisect_left(coord, lo)
        right = bisect_left(coord, hi)
        if left >= right:
            return 0

        seg = self.seg[p]
        base = len(seg) // 2
        left += base
        right += base
        ans = 0

        while left < right:
            if left & 1:
                if seg[left] > ans:
                    ans = seg[left]
                left += 1
            if right & 1:
                right -= 1
                if seg[right] > ans:
                    ans = seg[right]
            left >>= 1
            right >>= 1

        return ans

    def query(self, left, right, lo, hi):
        if left >= right or lo >= hi:
            return 0

        left = left - 1 + self.size
        right = right - 1 + self.size
        ans = 0

        while left < right:
            if left & 1:
                v = self.query_node(left, lo, hi)
                if v > ans:
                    ans = v
                left += 1
            if right & 1:
                right -= 1
                v = self.query_node(right, lo, hi)
                if v > ans:
                    ans = v
            left >>= 1
            right >>= 1

        return ans


def main():
    input = sys.stdin.buffer.readline
    n, m, q = map(int, input().split())

    intervals = []
    directions = []

    for _ in range(m):
        s, t = map(int, input().split())
        if s < t:
            intervals.append((s, t))
            directions.append(1)
        else:
            intervals.append((t, s))
            directions.append(-1)

    queries = [tuple(map(int, input().split())) for _ in range(q)]

    bad = [0] * (m + 1)

    # Opposite directions on the same pair of endpoints are incompatible.
    last = {}
    for i, ((l, r), d) in enumerate(zip(intervals, directions), 1):
        opposite_key = (l, r, -d)
        if opposite_key in last:
            bad[i] = last[opposite_key]
        last[(l, r, d)] = i

    # Equal-direction proper crossings are incompatible.
    tree = RangeTree2D(intervals, n)

    for wanted_direction in (1, -1):
        tree.clear()

        for i, ((l, r), d) in enumerate(zip(intervals, directions), 1):
            if d != wanted_direction:
                continue

            # Earlier intervals [a,b] with a < l < b < r.
            # Starts are in [1,l), ends are in [l+1,r).
            v1 = tree.query(1, l, l + 1, r)

            # Earlier intervals [a,b] with l < a < r < b.
            # Starts are in [l+1,r), ends are in [r+1,n+1).
            v2 = tree.query(l + 1, r, r + 1, n + 1)

            if v1 > bad[i]:
                bad[i] = v1
            if v2 > bad[i]:
                bad[i] = v2

            tree.update(l, r, i)

    size = 1
    while size < m:
        size <<= 1

    seg = [0] * (2 * size)
    for i in range(1, m + 1):
        seg[size + i - 1] = bad[i]

    for i in range(size - 1, 0, -1):
        seg[i] = max(seg[i << 1], seg[i << 1 | 1])

    def range_max(left, right):
        left = left - 1 + size
        right = right + size
        ans = 0

        while left < right:
            if left & 1:
                if seg[left] > ans:
                    ans = seg[left]
                left += 1
            if right & 1:
                right -= 1
                if seg[right] > ans:
                    ans = seg[right]
            left >>= 1
            right >>= 1

        return ans

    out = []
    for left, right in queries:
        out.append("Yes\n" if range_max(left, right) < left else "No\n")

    sys.stdout.write("".join(out))


if __name__ == "__main__":
    main()

import sys
from bisect import bisect_right


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    q = data[0]
    queries = data[1:1 + q]

    limit = 1_000_000

    # Smallest prime factor sieve.
    spf = list(range(limit + 1))
    for p in range(2, 1001):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p

    # Number of distinct prime factors for every integer.
    distinct = bytearray(limit + 1)
    squares = []

    for x in range(2, limit + 1):
        p = spf[x]
        y = x // p
        distinct[x] = distinct[y] + (spf[y] != p)

        if distinct[x] == 2:
            squares.append(x * x)

    answers = []
    for a in queries:
        answers.append(str(squares[bisect_right(squares, a) - 1]))

    sys.stdout.write("\n".join(answers))


if __name__ == "__main__":
    solve()

import sys

ONE_HOT = (1, 2, 4)
MASK_TO_POS = {1: 0, 2: 1, 4: 2}
NEG_INF = -10**30


def keep_best(best, key, score, index):
    first, second = best[key]
    if score > first[0]:
        best[key] = ((score, index), first)
    elif score > second[0]:
        best[key] = (first, (score, index))


def solve_case(n, k, cakes):
    m = 2 * k

    # Each cake is (dominant value, dominant mask, (X, Y, Z)).
    cakes.sort(key=lambda item: item[0], reverse=True)

    dominant = [cake[0] for cake in cakes]
    masks = [cake[1] for cake in cakes]
    values = [cake[2] for cake in cakes]

    pref_sum = [0] * (n + 1)
    pref_xor = [0] * (n + 1)
    for i in range(n):
        pref_sum[i + 1] = pref_sum[i] + dominant[i]
        pref_xor[i + 1] = pref_xor[i] ^ masks[i]

    answer = -1

    # No special cakes: choose the first m cakes with their dominant coordinates.
    if pref_xor[m] == 0:
        answer = pref_sum[m]

    # Exactly one special cake.
    q = m - 1
    base_sum = pref_sum[q]
    base_xor = pref_xor[q]

    for i in range(n):
        if i < q:
            regular_sum = base_sum - dominant[i] + dominant[q]
            regular_xor = base_xor ^ masks[i] ^ masks[q]
        else:
            regular_sum = base_sum
            regular_xor = base_xor

        if regular_xor in MASK_TO_POS:
            special_value = values[i][MASK_TO_POS[regular_xor]]
            answer = max(answer, regular_sum + special_value)

    def new_best():
        return [[(NEG_INF, -1), (NEG_INF, -1)] for _ in range(8)]

    # Exactly two special cakes.
    q = m - 2
    base_sum = pref_sum[q]
    base_xor = pref_xor[q]

    # Both specials are inside [0, q).
    inside_delta = new_best()
    for i in range(q):
        for assigned in ONE_HOT:
            delta = assigned ^ masks[i]
            gain = values[i][MASK_TO_POS[assigned]] - dominant[i]
            keep_best(inside_delta, delta, gain, i)

    target = base_xor ^ masks[q] ^ masks[q + 1]
    for key_a in range(8):
        key_b = key_a ^ target
        for gain_a, index_a in inside_delta[key_a]:
            if index_a < 0:
                continue
            for gain_b, index_b in inside_delta[key_b]:
                if index_b < 0 or index_a == index_b:
                    continue
                answer = max(
                    answer,
                    base_sum
                    + dominant[q]
                    + dominant[q + 1]
                    + gain_a
                    + gain_b,
                )

    # One special is inside [0, q), and the other is q.
    inside_delta = new_best()
    for i in range(q):
        for assigned in ONE_HOT:
            delta = assigned ^ masks[i]
            gain = values[i][MASK_TO_POS[assigned]] - dominant[i]
            keep_best(inside_delta, delta, gain, i)

    target = base_xor ^ masks[q + 1]
    for delta_i in range(8):
        assigned_q = target ^ delta_i
        if assigned_q not in MASK_TO_POS:
            continue
        value_q = values[q][MASK_TO_POS[assigned_q]]
        for gain_i, index_i in inside_delta[delta_i]:
            if index_i < 0:
                continue
            answer = max(
                answer,
                base_sum + dominant[q + 1] + gain_i + value_q,
            )

    # One special is inside [0, q), and the other is greater than q.
    outside_assigned = new_best()
    for j in range(q + 1, n):
        for assigned in ONE_HOT:
            keep_best(
                outside_assigned,
                assigned,
                values[j][MASK_TO_POS[assigned]],
                j,
            )

    target = base_xor ^ masks[q]
    for delta_i in range(8):
        assigned_j = target ^ delta_i
        if assigned_j not in MASK_TO_POS:
            continue
        for gain_i, index_i in inside_delta[delta_i]:
            if index_i < 0:
                continue
            for gain_j, index_j in outside_assigned[assigned_j]:
                if index_j < 0:
                    continue
                answer = max(
                    answer,
                    base_sum
                    + dominant[q]
                    + gain_i
                    + gain_j,
                )

    # Both specials are at least q.
    outside_assigned = new_best()
    for i in range(q, n):
        for assigned in ONE_HOT:
            keep_best(
                outside_assigned,
                assigned,
                values[i][MASK_TO_POS[assigned]],
                i,
            )

    target = base_xor
    for assigned_a in range(8):
        assigned_b = assigned_a ^ target
        for gain_a, index_a in outside_assigned[assigned_a]:
            if index_a < 0:
                continue
            for gain_b, index_b in outside_assigned[assigned_b]:
                if index_b < 0 or index_a == index_b:
                    continue
                answer = max(answer, base_sum + gain_a + gain_b)

    return answer


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    t = next(it)
    answers = []

    for _ in range(t):
        n = next(it)
        k = next(it)
        cakes = []

        for _ in range(n):
            x = next(it)
            y = next(it)
            z = next(it)

            if x >= y and x >= z:
                cakes.append((x, 1, (x, y, z)))
            elif y >= z:
                cakes.append((y, 2, (x, y, z)))
            else:
                cakes.append((z, 4, (x, y, z)))

        answers.append(str(solve_case(n, k, cakes)))

    sys.stdout.write("\n".join(answers))


if __name__ == "__main__":
    main()

import sys


def solve():
    input = sys.stdin.readline

    n = int(input())
    s = input().strip()
    t = input().strip()

    mapping = [-1] * 26

    for a, b in zip(s, t):
        x = ord(a) - ord('a')
        y = ord(b) - ord('a')
        if mapping[x] != -1 and mapping[x] != y:
            print(-1)
            return
        mapping[x] = y

    changed = sum(
        1 for x in range(26)
        if mapping[x] != -1 and mapping[x] != x
    )

    state = [0] * 26
    cycles = 0

    def dfs(v):
        nonlocal cycles
        state[v] = 1

        w = mapping[v]
        if w != -1 and w != v:
            if state[w] == 0:
                dfs(w)
            elif state[w] == 1:
                cycles += 1

        state[v] = 2

    for v in range(26):
        if state[v] == 0:
            dfs(v)

    if cycles > 0 and len(set(s)) == 26:
        print(-1)
    else:
        print(changed + cycles)


if __name__ == "__main__":
    solve()

