    solve()

from functools import lru_cache


class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(bound: int) -> int:
            if bound <= 0:
                return 0

            digits = list(map(int, str(bound)))
            n = len(digits)
            total = 0

            for target_sum in range(1, 9 * n + 1):
                @lru_cache(None)
                def dp(pos: int, digit_sum: int, product_mod: int,
                       started: bool, tight: bool) -> int:
                    if digit_sum > target_sum:
                        return 0
                    if digit_sum + 9 * (n - pos) < target_sum:
                        return 0

                    if pos == n:
                        return int(
                            started
                            and digit_sum == target_sum
                            and product_mod == 0
                        )

                    limit = digits[pos] if tight else 9
                    result = 0

                    for d in range(limit + 1):
                        next_tight = tight and (d == limit if tight else False)
                        if tight:
                            next_tight = d == digits[pos]

                        if not started and d == 0:
                            result += dp(
                                pos + 1,
                                0,
                                0,
                                False,
                                next_tight
                            )
                        else:
                            if not started:
                                next_sum = d
                                next_product = d % target_sum
                            else:
                                next_sum = digit_sum + d
                                next_product = (product_mod * d) % target_sum

                            result += dp(
                                pos + 1,
                                next_sum,
                                next_product,
                                True,
                                next_tight
                            )

                    return result

                total += dp(0, 0, 0, False, True)

            return total

        return count_up_to(r) - count_up_to(l - 1)

import sys
import math


def integer_cuberoot(n: int) -> int:
    lo, hi = 0, 1
    while hi * hi * hi <= n:
        hi *= 2
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if mid * mid * mid <= n:
            lo = mid
        else:
            hi = mid
    return lo


def solve() -> None:
    n = int(sys.stdin.readline())

    limit = integer_cuberoot(n)

    for d in range(1, limit + 1):
        if n % d != 0:
            continue

        q = n // d
        discriminant = 12 * q - 3 * d * d
        if discriminant < 0:
            continue

        s = math.isqrt(discriminant)
        if s * s != discriminant:
            continue

        numerator = s - 3 * d
        if numerator <= 0 or numerator % 6 != 0:
            continue

        y = numerator // 6
        x = y + d

        if y > 0 and x * x * x - y * y * y == n:
            print(x, y)
            return

    print(-1)


if __name__ == "__main__":
    solve()

import sys
from collections import deque

sys.setrecursionlimit(1_000_000)


class Dinic:
    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        forward = [to, cap, len(self.graph[to])]
        backward = [fr, 0, len(self.graph[fr])]
        self.graph[fr].append(forward)
        self.graph[to].append(backward)

    def max_flow(self, source, sink):
        flow = 0
        inf = 10**18

        while True:
            level = [-1] * self.n
            level[source] = 0
            queue = deque([source])

            while queue:
                v = queue.popleft()
                for to, cap, _ in self.graph[v]:
                    if cap > 0 and level[to] < 0:
                        level[to] = level[v] + 1
                        queue.append(to)

            if level[sink] < 0:
                return flow

            it = [0] * self.n

            def dfs(v, pushed):
                if v == sink:
                    return pushed

                while it[v] < len(self.graph[v]):
                    edge = self.graph[v][it[v]]
                    to, cap, rev = edge

                    if cap > 0 and level[to] == level[v] + 1:
                        amount = dfs(to, min(pushed, cap))
                        if amount:
                            edge[1] -= amount
                            self.graph[to][rev][1] += amount
                            return amount

                    it[v] += 1

                return 0

            while True:
                pushed = dfs(source, inf)
                if pushed == 0:
                    break
                flow += pushed


def minimum_selected_edges(n, m, edges, distance):
    if distance == 0:
        return 0

    label_count = n * distance
    source = label_count
    sink = source + 1
    dinic = Dinic(sink + 1)

    inf = m + 1

    def label(vertex, level):
        return vertex * distance + level

    # Vertex 1 must have potential 0:
    # every positive threshold label is on the sink side.
    for level in range(distance):
        dinic.add_edge(label(0, level), sink, inf)

    # Vertex N must have potential at least distance:
    # every threshold label is on the source side.
    for level in range(distance):
        dinic.add_edge(source, label(n - 1, level), inf)

    # Threshold monotonicity:
    # z[v][i+1] => z[v][i].
    for vertex in range(n):
        for level in range(1, distance):
            dinic.add_edge(label(vertex, level), label(vertex, level - 1), inf)

    for u, v in edges:
        u -= 1
        v -= 1

        for level in range(distance):
            # Capacity 1. This is cut exactly when the edge's
            # potential difference is one at this threshold.
            dinic.add_edge(label(v, level), label(u, level), 1)

            # Infinite capacity: d_v >= level+1 implies d_u >= level.
            # This enforces d_v <= d_u + 1.
            if level >= 1:
                dinic.add_edge(
                    label(v, level),
                    label(u, level - 1),
                    inf,
                )

    return dinic.max_flow(source, sink)


def main():
