    fenwick = Fenwick(n)
    answer = 0

    for j, x in enumerate(p, 1):
        not_greater = fenwick.sum(x)
        larger = (j - 1) - not_greater

        # x crosses boundaries j-larger, ..., j-1.
        answer += larger * (2 * j - larger - 1) // 2

        fenwick.add(x, 1)

    print(answer)


