import sys

MOD = 998244353
BLOCK = 46


def solve():
    input = sys.stdin.buffer.readline

    H, W = map(int, input().split())
    a = [list(map(int, input().split())) for _ in range(H)]

    Q, sh, sw = map(int, input().split())
    h, w = sh - 1, sw - 1

    ops = []
    positions = []

    for _ in range(Q):
        d, x = input().split()
        x = int(x)

        if d == b"L":
            w -= 1
        elif d == b"R":
            w += 1
        elif d == b"U":
            h -= 1
        else:
            h += 1

        ops.append((h, w, x))
        positions.append((h, w))

    answers = []

    for left in range(0, Q, BLOCK):
        right = min(Q, left + BLOCK)

        r0, c0 = H, W
        r1, c1 = -1, -1

        for i in range(left, right):
            r, c = positions[i]
            if r < r0:
                r0 = r
            if r > r1:
                r1 = r
            if c < c0:
                c0 = c
            if c > c1:
                c1 = c

        pre = [[0] * W for _ in range(H)]
        for r in range(H):
            ar = a[r]
            pr = pre[r]
            for c in range(W):
                if r == 0 and c == 0:
                    pr[c] = ar[c]
                else:
                    s = 0
                    if r:
                        s += pre[r - 1][c]
                    if c:
                        s += pr[c - 1]
                    pr[c] = ar[c] * s % MOD

        suf = [[0] * W for _ in range(H)]
        for r in range(H - 1, -1, -1):
            ar = a[r]
            sr = suf[r]
            for c in range(W - 1, -1, -1):
                if r == H - 1 and c == W - 1:
                    s = 1
                else:
                    s = 0
                    if r + 1 < H:
                        s += suf[r + 1][c]
                    if c + 1 < W:
                        s += sr[c + 1]
                sr[c] = ar[c] * s % MOD

        local = [
            pre[r][c0:c1 + 1]
            for r in range(r0, r1 + 1)
        ]
        local_h = r1 - r0 + 1
        local_w = c1 - c0 + 1

        def through_box():
            if r1 == H - 1 and c1 == W - 1:
                return local[-1][-1]

            total = 0

            if r1 < H - 1:
                suffix_row = suf[r1 + 1]
                last_local_row = local[-1]
                for c in range(c0, c1 + 1):
                    total += last_local_row[c - c0] * suffix_row[c]

            if c1 < W - 1:
                right_col = c1 + 1
                last_local_col = local_w - 1
                for r in range(r0, r1 + 1):
                    total += local[r - r0][last_local_col] * suf[r][right_col]

            return total % MOD

        unchanged = (pre[H - 1][W - 1] - through_box()) % MOD

        for i in range(left, right):
            r, c, value = ops[i]
            a[r][c] = value

            for rr in range(r, r1 + 1):
                lr = rr - r0
                row = local[lr]

                for cc in range(c, c1 + 1):
                    lc = cc - c0

                    if rr == 0 and cc == 0:
                        row[lc] = a[rr][cc]
                        continue

                    ways = 0

                    if rr:
                        if rr == r0:
                            ways += pre[rr - 1][cc]
                        else:
                            ways += local[lr - 1][lc]

                    if cc:
                        if cc == c0:
                            ways += pre[rr][cc - 1]
                        else:
                            ways += row[lc - 1]

                    row[lc] = a[rr][cc] * ways % MOD

            answers.append(str((unchanged + through_box()) % MOD))

    sys.stdout.write("\n".join(answers))


if __name__ == "__main__":
    solve()

import sys


def mat_mul(X, Y, mod):
    n = len(X)
    Z = [[0] * n for _ in range(n)]
    for i in range(n):
        zi = Z[i]
        xi = X[i]
        for k, x in enumerate(xi):
            if x:
                yk = Y[k]
                for j in range(n):
                    zi[j] += x * yk[j]
        for j in range(n):
            zi[j] %= mod
    return Z


def mat_pow(A, e, mod):
    n = len(A)
    R = [[0] * n for _ in range(n)]
    for i in range(n):
        R[i][i] = 1 % mod

    while e:
        if e & 1:
            R = mat_mul(R, A, mod)
        A = mat_mul(A, A, mod)
        e >>= 1
    return R


def main():
    input = sys.stdin.readline
    N, p = map(int, input().split())
    A = [list(map(int, input().split())) for _ in range(N)]

    if p == 2:
        B = [row[:] for row in A]
        for i in range(N):
            for j in range(N):
                if B[i][j] == 0:
                    B[i][j] = 1
        ans = mat_mul(B, B, 2)
        for row in ans:
            print(*row)
        return

    zeros = []
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                zeros.append((i, j))

    ans = mat_pow(A, p, p)

    correction = [[0] * N for _ in range(N)]

    if p == 3:
        for u, v in zeros:
            if u == v:
                for j in range(N):
                    correction[u][j] += A[u][j]
                for i in range(N):
                    correction[i][u] += A[i][u]
            else:
                correction[u][v] += A[v][u]
    else:
        for u, v in zeros:
            if u == v:
                for j in range(N):
                    correction[u][j] += A[u][j]
                for i in range(N):
                    correction[i][u] += A[i][u]

    sign = 1 if len(zeros) % 2 == 0 else p - 1
    for i in range(N):
        for j in range(N):
            ans[i][j] = sign * (ans[i][j] + correction[i][j]) % p

    for row in ans:
        print(*row)


if __name__ == "__main__":
    main()

import sys

MOD = 998244353
sys.setrecursionlimit(10000)

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, m = data[0], data[1]
    a = [x - 1 for x in data[2:]]

    rev = [[] for _ in range(n)]
    indeg = [0] * n
    for i, p in enumerate(a):
        rev[p].append(i)
        indeg[p] += 1

    queue = [i for i in range(n) if indeg[i] == 0]
    head = 0
    while head < len(queue):
        v = queue[head]
        head += 1
        p = a[v]
        indeg[p] -= 1
        if indeg[p] == 0:
            queue.append(p)

    in_cycle = [indeg[i] > 0 for i in range(n)]

    def tree_dp(v):
        result = None

        for child in rev[v]:
            if in_cycle[child]:
                continue

            child_dp = tree_dp(child)

            running = 0
            for t in range(m):
                running += child_dp[t]
                if running >= MOD:
                    running -= MOD
                child_dp[t] = running

            if result is None:
                result = child_dp
            else:
                for t in range(m):
                    result[t] = result[t] * child_dp[t] % MOD
                del child_dp

        if result is None:
            result = [1] * m

        return result

    visited_cycle = [False] * n
    answer = 1

    for start in range(n):
        if not in_cycle[start] or visited_cycle[start]:
            continue

        cycle = []
        v = start
        while not visited_cycle[v]:
            visited_cycle[v] = True
            cycle.append(v)
            v = a[v]

        component_dp = None
        for v in cycle:
            current = tree_dp(v)
            if component_dp is None:
                component_dp = current
            else:
                for t in range(m):
                    component_dp[t] = component_dp[t] * current[t] % MOD
                del current

        component_count = sum(component_dp) % MOD
        answer = answer * component_count % MOD

    print(answer)

if __name__ == "__main__":
    solve()

