import sys


def cross(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    points = [(data[i], data[i + 1]) for i in range(1, 2 * n + 1, 2)]

    hull = []
    best_num = None
    best_den = 1

    for x, h in points:
        if hull:
            lo, hi = 0, len(hull) - 1

            # Find the vertex minimizing (h - hull_y) / (x - hull_x).
            while lo < hi:
                mid = (lo + hi) // 2
                a = hull[mid]
                b = hull[mid + 1]

                left = (h - a[1]) * (x - b[0])
                right = (h - b[1]) * (x - a[0])

                if left <= right:
                    hi = mid
                else:
                    lo = mid + 1

            px, py = hull[lo]
            num = x * py - px * h
            den = x - px

            if best_num is None or num * best_den > best_num * den:
                best_num = num
                best_den = den

        new_point = (x, h)
        while len(hull) >= 2 and cross(hull[-2], hull[-1], new_point) >= 0:
            hull.pop()
        hull.append(new_point)

    if best_num is None or best_num < 0:
        print(-1)
    else:
        print("{:.18f}".format(best_num / best_den))


if __name__ == "__main__":
    solve()

class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        n = len(s)
        answer = n

        candidates = {1}
        for value in counts:
            if value > 0:
                candidates.add(value)

        for i in range(26):
            for j in range(i + 1, 26):
                total = counts[i] + counts[j]
                candidates.add(total // 2)
                candidates.add((total + 1) // 2)

        inf = 10**18

        for target in candidates:
            if target <= 0 or target > n:
                continue

            dp = [inf] * (target + 1)
            dp[0] = 0

            for original in counts[:25]:
                prefix = [inf] * (target + 1)
                best = inf
                for incoming in range(target + 1):
                    best = min(best, dp[incoming] - incoming)
                    prefix[incoming] = best

                suffix = [inf] * (target + 1)
                best = inf
                for incoming in range(target, -1, -1):
                    best = min(best, dp[incoming] + incoming)
                    suffix[incoming] = best

                next_dp = [inf] * (target + 1)

                for final_count in (0, target):
                    shift = original - final_count

                    for outgoing in range(target + 1):
                        t = outgoing - shift

                        if t < 0:
                            transition = suffix[0] - t
                        elif t > target:
                            transition = prefix[target] + t
                        else:
                            transition = min(
                                prefix[t] + t,
                                suffix[t] - t,
                            )

                        next_dp[outgoing] = min(
                            next_dp[outgoing],
                            transition + outgoing,
                        )

                dp = next_dp

            original = counts[25]
            best_final = inf

            for incoming, base in enumerate(dp):
                best_final = min(
                    best_final,
                    base + original + incoming,
                    base + abs(original + incoming - target),
                )

            answer = min(answer, best_final)

        return answer

import sys


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    a = data[1:1 + n]
    max_sum = 2 * max(a)

    normalized_sums = []
    modulus = 1

    while modulus <= max_sum:
        groups = {}
        for x in a:
            r = x % modulus
            if r in groups:
                groups[r][0] += 1
                groups[r][1] += x
            else:
                groups[r] = [1, x]

        total = 0

        for r, (count_r, sum_r) in groups.items():
            complement = (-r) % modulus
            if r > complement:
                continue

            if r == complement:
                # All unordered pairs, including diagonals, within this group.
                # Each element occurs count_r + 1 times among pair coordinates.
                total += (count_r + 1) * sum_r
            else:
                other = groups.get(complement)
                if other is not None:
                    count_s, sum_s = other
                    total += sum_r * count_s + sum_s * count_r

        normalized_sums.append(total // modulus)
        modulus <<= 1

    answer = 0
    for k in range(len(normalized_sums)):
        next_value = normalized_sums[k + 1] if k + 1 < len(normalized_sums) else 0
        answer += normalized_sums[k] - 2 * next_value

    print(answer)


if __name__ == "__main__":
    solve()

from typing import List


class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        size = [1] * n
        components = n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            nonlocal components
            ra = find(a)
            rb = find(b)

            if ra == rb:
                return

            if size[ra] < size[rb]:
                ra, rb = rb, ra

            parent[rb] = ra
            size[ra] += size[rb]
            components -= 1

        owner = [-1] * (threshold + 1)

        for index, value in enumerate(nums):
            if value > threshold:
                continue

            for multiple in range(value, threshold + 1, value):
                if owner[multiple] == -1:
                    owner[multiple] = index
                else:
                    union(index, owner[multiple])

        return components
